/**
 * The research tree (#7): ~1,100 nodes, generated by rules from a few hand-set pieces, laid out like the owner's
 * reference (notes/reference in the workshop): a start in the middle, one cluster per turret kind on an outer ring,
 * global clusters between them, bridges and synergies across, expensive keystones at the rim.
 *
 * A node can be bought when it touches a bought node (links, either direction) and every node in `requiresAll`
 * is bought. Cost grows with the path length from the start, so a far direction costs more by distance alone.
 */
import { TURRET_TYPES, turretType, type TurretKind } from "./turrets.ts";
import type { DamageType } from "./enemies.ts";
import { BALANCE } from "./balance.ts";

export type PatternField = "radius" | "burnSeconds" | "jumps" | "width" | "factor" | "seconds" | "angle";

export type Effect =
  | { kind: "unlock"; turret: TurretKind }
  | { kind: "capacity"; turret: TurretKind; add: number }
  | { kind: "capacityMul"; turret: TurretKind; mul: number }
  | { kind: "fireRate"; turret: TurretKind; mul: number }
  | { kind: "range"; turret: TurretKind; add: number }
  | { kind: "damage"; turret: TurretKind; mul: number }
  | { kind: "turnRate"; turret: TurretKind; mul: number }
  | { kind: "pattern"; turret: TurretKind; field: PatternField; add: number }
  | { kind: "abilityUnlock" }
  | { kind: "abilityDamage"; mul: number }
  | { kind: "abilityRadius"; add: number }
  | { kind: "abilityCooldown"; mul: number };

export type NodeSize = "start" | "small" | "notable" | "keystone" | "entry" | "synergy";

export interface ResearchNode {
  id: string;
  name: string;
  cost: number;
  /** Neighbours in the tree. Buyable when any neighbour is bought. */
  links: string[];
  /** Must all be bought too (synergies across clusters). */
  requiresAll?: string[];
  effects: Effect[];
  /** Nodes of one group get dearer with every node of the group already owned: cost × growth^owned. */
  group?: { id: string; growth: number };
  size: NodeSize;
  /** Cluster the node belongs to (turret kind, global theme, ability, bridge, start). */
  cluster: string;
  /** Layout position in tree units. */
  x: number;
  y: number;
}

/** The start node; always owned, never bought. */
export const ROOT = "start";

const SIZE_COST: Record<NodeSize, number> = { start: 0, small: 1, notable: 3, keystone: 10, entry: 1, synergy: 5 };
const UNLOCK_COST = 60;
const UNLOCK_GROWTH = 4;

/** Drawn radius of a node in tree units (ui/treeView.ts); keystones and the start get an outer ring at 1.35×. */
export const NODE_RADIUS: Record<NodeSize, number> = { start: 1.5, entry: 1.1, keystone: 1.25, notable: 0.75, synergy: 0.85, small: 0.38 };

const CLUSTER_RADIUS = 40;
const ENTRY_RADIUS = 6;
/** Global clusters sit in every other gap between turret spokes, far enough out that their rings clear the spokes (#23). */
const GLOBAL_RADIUS = 26;
/** Distance between the rings of a global cluster. */
const RING_STEP = 1.9;
const ABILITY_RADIUS = 18;
/** Distance between two steps of an ability line. */
const ABILITY_STEP = 1.45;
const STEP = 2.3;

interface Draft extends Omit<ResearchNode, "cost"> {
  /** Cost override (unlock entries). */
  fixedCost?: number;
}

const rad = (deg: number) => (deg * Math.PI) / 180;

export function buildTree(): ResearchNode[] {
  const nodes = new Map<string, Draft>();
  const add = (n: Draft) => {
    if (nodes.has(n.id)) throw new Error(`duplicate node ${n.id}`);
    nodes.set(n.id, n);
    return n;
  };
  const link = (a: string, b: string) => {
    nodes.get(a)!.links.push(b);
    nodes.get(b)!.links.push(a);
  };

  add({ id: ROOT, name: "Kommando", links: [], effects: [], size: "start", cluster: "start", x: 0, y: 0 });

  const kinds = TURRET_TYPES.map((t) => t.id);
  const angleOf = (i: number) => -90 + (360 / kinds.length) * i;

  kinds.forEach((k, i) => turretCluster(k, angleOf(i)));
  GLOBALS.forEach((g, i) => globalCluster(g, angleOf(2 * i) + 360 / kinds.length / 2));
  abilityCluster(angleOf(11) + 360 / kinds.length / 2);
  kinds.forEach((k, i) => bridge(k, kinds[(i + 1) % kinds.length]!, angleOf(i) + 360 / kinds.length / 2));

  function turretCluster(k: TurretKind, angle: number) {
    const t = turretType(k);
    const a = rad(angle);
    const ex = Math.cos(a) * ENTRY_RADIUS;
    const ey = Math.sin(a) * ENTRY_RADIUS;
    // The entry sits close to the start: the first decision is which kind to unlock.
    add({ id: k, name: t.name, links: [], effects: [{ kind: "unlock", turret: k }, { kind: "capacity", turret: k, add: 2 }], group: { id: "unlock", growth: UNLOCK_GROWTH }, fixedCost: UNLOCK_COST, size: "entry", cluster: k, x: ex, y: ey });
    link(ROOT, k);
    const cx = Math.cos(a) * CLUSTER_RADIUS;
    const cy = Math.sin(a) * CLUSTER_RADIUS;
    const hub = add({ id: `${k}-hub`, name: `${t.name}: Werkstatt`, links: [], effects: [{ kind: "capacity", turret: k, add: 1 }], size: "notable", cluster: k, x: cx, y: cy });
    // Two small steps from the entry to the workshop.
    let prev: string = k;
    for (let s = 1; s <= 2; s++) {
      const r = ENTRY_RADIUS + ((CLUSTER_RADIUS - ENTRY_RADIUS) * s) / 3;
      add({ id: `${k}-path-${s}`, name: `${t.name}: Grundlagen ${s}`, links: [], effects: [{ kind: "fireRate", turret: k, mul: 1.05 }], size: "small", cluster: k, x: Math.cos(a) * r, y: Math.sin(a) * r });
      link(prev, `${k}-path-${s}`);
      prev = `${k}-path-${s}`;
    }
    link(prev, hub.id);

    const chains = CHAINS(k);
    const tips: string[][] = [];
    // Chains leave the workshop side by side and fan out slowly, like spokes of a half wheel.
    const ux = Math.cos(a);
    const uy = Math.sin(a);
    chains.forEach((c, j) => {
      const lane = j - (chains.length - 1) / 2;
      let last = hub.id;
      const ids: string[] = [];
      for (let s = 1; s <= c.length; s++) {
        const notable = s % 4 === 0;
        const keystone = s === c.length;
        const d = 1.2 + s * STEP;
        const side = lane * (1.4 + d * 0.09);
        const id = `${k}-${c.id}-${s}`;
        add({
          id,
          name: keystone ? `${t.name}: ${c.keystoneName}` : notable ? `${t.name}: ${c.notableName} ${s / 4}` : `${t.name}: ${c.name} ${s}`,
          links: [],
          effects: keystone ? c.keystone : notable ? c.notable : s % 2 === 0 && c.smallAlt ? c.smallAlt : c.small,
          size: keystone ? "keystone" : notable ? "notable" : "small",
          cluster: k,
          x: cx + ux * d - uy * side,
          y: cy + uy * d + ux * side,
        });
        link(last, id);
        last = id;
        ids.push(id);
      }
      tips.push(ids);
    });
    // Rungs between neighbouring chains, every third step: the ring look of the reference, and side ways in.
    for (let j = 0; j + 1 < tips.length; j++) {
      for (let s = 3; s < Math.min(tips[j]!.length, tips[j + 1]!.length); s += 3) link(tips[j]![s - 1]!, tips[j + 1]![s - 1]!);
    }
  }

  function globalCluster(g: GlobalTheme, angle: number) {
    const a = rad(angle);
    const cx = Math.cos(a) * GLOBAL_RADIUS;
    const cy = Math.sin(a) * GLOBAL_RADIUS;
    const hubId = `g-${g.id}`;
    add({ id: hubId, name: g.name, links: [], effects: g.notable(), size: "notable", cluster: g.id, x: cx, y: cy });
    link(ROOT, hubId);
    const rings = [6, 12, 16];
    let inner: string[] = [hubId];
    // Rings count from the outward side, half a step off it: every ring then leaves a gap towards the start, so the
    // line from the start to the hub crosses none of them, and the keystone (index 0) faces outward (#23).
    rings.forEach((count, r) => {
      const ring: string[] = [];
      for (let i = 0; i < count; i++) {
        const ang = a + (Math.PI / count) * (2 * i + 1);
        const notable = (i + r) % 5 === 4;
        // The keystone sits a little further out: its outer ring needs the room.
        const keystone = r === rings.length - 1 && i === 0;
        const id = `g-${g.id}-${r + 1}-${i + 1}`;
        add({
          id,
          name: keystone ? `${g.name}: ${g.keystoneName}` : `${g.name} ${r + 1}.${i + 1}`,
          links: [],
          effects: keystone ? g.keystone() : notable ? g.notable() : g.small(),
          size: keystone ? "keystone" : notable ? "notable" : "small",
          cluster: g.id,
          x: cx + Math.cos(ang) * ((r + 1) * RING_STEP + (keystone ? 1.2 : 0)),
          y: cy + Math.sin(ang) * ((r + 1) * RING_STEP + (keystone ? 1.2 : 0)),
        });
        ring.push(id);
      }
      // Each ring is a loop; every node of it hangs on the node at the same place around the ring inside.
      ring.forEach((id, i) => {
        link(id, ring[(i + 1) % ring.length]!);
        const parent = inner[Math.floor((i / ring.length) * inner.length)]!;
        if (!nodes.get(id)!.links.includes(parent)) link(id, parent);
      });
      inner = ring;
    });
  }

  function abilityCluster(angle: number) {
    const a = rad(angle);
    const cx = Math.cos(a) * ABILITY_RADIUS;
    const cy = Math.sin(a) * ABILITY_RADIUS;
    add({ id: "ability", name: "Präzisionsschuss", links: [], effects: [{ kind: "abilityUnlock" }], size: "notable", cluster: "ability", x: cx, y: cy });
    link(ROOT, "ability");
    const lines: { id: string; name: string; small: Effect; notable: Effect }[] = [
      { id: "dmg", name: "Schaden", small: { kind: "abilityDamage", mul: 1.15 }, notable: { kind: "abilityDamage", mul: 2 } },
      { id: "radius", name: "Fläche", small: { kind: "abilityRadius", add: 0.1 }, notable: { kind: "abilityRadius", add: 0.5 } },
      { id: "cd", name: "Abklingzeit", small: { kind: "abilityCooldown", mul: 0.95 }, notable: { kind: "abilityCooldown", mul: 0.75 } },
    ];
    lines.forEach((l, j) => {
      const off = rad(angle + (j - 1) * 20);
      let last = "ability";
      for (let s = 1; s <= 10; s++) {
        const notable = s % 5 === 0;
        const id = `ability-${l.id}-${s}`;
        add({ id, name: `Präzisionsschuss: ${l.name} ${s}`, links: [], effects: [notable ? l.notable : l.small], size: notable ? "notable" : "small", cluster: "ability", x: cx + Math.cos(off) * (2 + s * ABILITY_STEP), y: cy + Math.sin(off) * (2 + s * ABILITY_STEP) });
        link(last, id);
        last = id;
      }
    });
  }

  /** A path between two neighbouring turret clusters, and a synergy node that needs both kinds. */
  function bridge(a: TurretKind, b: TurretKind, angle: number) {
    const from = `${a}-hub`;
    const to = `${b}-hub`;
    const fa = nodes.get(from)!;
    const fb = nodes.get(to)!;
    const r = rad(angle);
    // Bend the path outward through the gap between the clusters.
    const mx = Math.cos(r) * CLUSTER_RADIUS * 1.12;
    const my = Math.sin(r) * CLUSTER_RADIUS * 1.12;
    let last = from;
    for (let s = 1; s <= 3; s++) {
      const t = s / 4;
      const x = (1 - t) * (1 - t) * fa.x + 2 * (1 - t) * t * mx + t * t * fb.x;
      const y = (1 - t) * (1 - t) * fa.y + 2 * (1 - t) * t * my + t * t * fb.y;
      const id = `bridge-${a}-${b}-${s}`;
      add({ id, name: `Verbindung ${turretType(a).name}–${turretType(b).name} ${s}`, links: [], effects: [{ kind: "range", turret: a, add: 0.1 }, { kind: "range", turret: b, add: 0.1 }], size: "small", cluster: "bridge", x, y });
      link(last, id);
      last = id;
    }
    link(last, to);
    const synergyId = `synergy-${a}-${b}`;
    add({
      id: synergyId,
      name: `Synergie ${turretType(a).name} + ${turretType(b).name}`,
      links: [],
      requiresAll: [a, b],
      effects: [{ kind: "capacity", turret: a, add: 2 }, { kind: "capacity", turret: b, add: 2 }, { kind: "fireRate", turret: a, mul: 1.25 }, { kind: "fireRate", turret: b, mul: 1.25 }],
      size: "synergy",
      cluster: "bridge",
      x: Math.cos(r) * CLUSTER_RADIUS * 1.35,
      y: Math.sin(r) * CLUSTER_RADIUS * 1.35,
    });
    link(`bridge-${a}-${b}-2`, synergyId);
  }

  // Cost from depth: breadth-first from the start.
  const depth = new Map<string, number>([[ROOT, 0]]);
  const queue = [ROOT];
  while (queue.length) {
    const id = queue.shift()!;
    for (const n of nodes.get(id)!.links) {
      if (!depth.has(n)) {
        depth.set(n, depth.get(id)! + 1);
        queue.push(n);
      }
    }
  }
  return [...nodes.values()].map(({ fixedCost, ...n }) => ({
    ...n,
    links: [...new Set(n.links)],
    cost: fixedCost ?? Math.round(BALANCE.costBase * BALANCE.costDepthGrowth ** (depth.get(n.id) ?? 0) * SIZE_COST[n.size]),
  }));
}

interface Chain {
  id: string;
  name: string;
  notableName: string;
  keystoneName: string;
  length: number;
  small: Effect[];
  /** Every second small node takes these instead, if set. */
  smallAlt?: Effect[];
  notable: Effect[];
  keystone: Effect[];
}

/** A small step of area for a kind's pattern; kinds without area get fire rate (#21: throughput is the main axis). */
function areaStep(k: TurretKind): Effect[] {
  const p = turretType(k).pattern;
  switch (p.kind) {
    case "splash": return [{ kind: "pattern", turret: k, field: "radius", add: 0.08 }];
    case "cone": return [{ kind: "pattern", turret: k, field: "angle", add: 3 }];
    case "pierce": return [{ kind: "pattern", turret: k, field: "width", add: 0.04 }];
    case "slow": return [{ kind: "pattern", turret: k, field: "seconds", add: 0.1 }];
    default: return [{ kind: "fireRate", turret: k, mul: 1.04 }];
  }
}

/** The chains of a turret cluster: the five stats every kind has, plus one for its weapon pattern. */
function CHAINS(k: TurretKind): Chain[] {
  const p = turretType(k).pattern;
  const patternChain: Chain = (() => {
    const base = { id: "pattern", length: 12 };
    switch (p.kind) {
      case "splash":
        return { ...base, name: "Sprengradius", notableName: "Druckwelle", keystoneName: "Flächenbrand", small: [{ kind: "pattern", turret: k, field: "radius", add: 0.12 }], notable: [{ kind: "pattern", turret: k, field: "radius", add: 0.5 }], keystone: [{ kind: "pattern", turret: k, field: "radius", add: 1.5 }, ...(p.burnSeconds ? [{ kind: "pattern" as const, turret: k, field: "burnSeconds" as const, add: 3 }] : [])] };
      case "cone":
        return { ...base, name: "Kegel", notableName: "Breitdüse", keystoneName: "Feuerwand", small: [{ kind: "pattern", turret: k, field: "angle", add: 4 }], notable: [{ kind: "pattern", turret: k, field: "burnSeconds", add: 1 }], keystone: [{ kind: "pattern", turret: k, field: "angle", add: 40 }] };
      case "chain":
        return { ...base, name: "Leitung", notableName: "Überschlag", keystoneName: "Gewittersturm", small: [{ kind: "fireRate", turret: k, mul: 1.06 }], notable: [{ kind: "pattern", turret: k, field: "jumps", add: 1 }], keystone: [{ kind: "pattern", turret: k, field: "jumps", add: 4 }] };
      case "pierce":
        return { ...base, name: "Projektilbreite", notableName: "Hohlladung", keystoneName: "Plasmalanze", small: [{ kind: "pattern", turret: k, field: "width", add: 0.05 }], notable: [{ kind: "pattern", turret: k, field: "width", add: 0.2 }], keystone: [{ kind: "pattern", turret: k, field: "width", add: 1 }] };
      case "slow":
        return { ...base, name: "Kälte", notableName: "Tiefkühlung", keystoneName: "Permafrost", small: [{ kind: "pattern", turret: k, field: "seconds", add: 0.15 }], notable: [{ kind: "pattern", turret: k, field: "factor", add: 0.08 }], keystone: [{ kind: "pattern", turret: k, field: "radius", add: 1.5 }] };
      case "beam":
        return { ...base, name: "Fokus", notableName: "Pulsfrequenz", keystoneName: "Dauerstrahl", small: [{ kind: "fireRate", turret: k, mul: 1.06 }], notable: [{ kind: "fireRate", turret: k, mul: 1.4 }], keystone: [{ kind: "fireRate", turret: k, mul: 3 }] };
      case "single":
        return { ...base, name: "Salve", notableName: "Panzerbrechend", keystoneName: "Sperrfeuer", small: [{ kind: "fireRate", turret: k, mul: 1.06 }], notable: [{ kind: "damage", turret: k, mul: 1.2 }], keystone: [{ kind: "fireRate", turret: k, mul: 2.5 }] };
    }
  })();
  return [
    { id: "cap", name: "Anzahl", notableName: "Nachschub", keystoneName: "Batterie", length: 12, small: [{ kind: "capacity", turret: k, add: 1 }], notable: [{ kind: "capacity", turret: k, add: 3 }], keystone: [{ kind: "capacityMul", turret: k, mul: 2 }] },
    { id: "rate", name: "Feuerrate", notableName: "Schnellladung", keystoneName: "Overdrive", length: 12, small: [{ kind: "fireRate", turret: k, mul: 1.1 }], notable: [{ kind: "fireRate", turret: k, mul: 1.6 }], keystone: [{ kind: "fireRate", turret: k, mul: 3 }] },
    patternChain,
    // #21: the mass scales, not the toughness — this chain feeds throughput; damage only at its milestones, moderate.
    { id: "dmg", name: "Munition", notableName: "Hartkern", keystoneName: "Vernichter", length: 12, small: [{ kind: "fireRate", turret: k, mul: 1.04 }], notable: [{ kind: "damage", turret: k, mul: 1.15 }], keystone: [{ kind: "damage", turret: k, mul: 1.5 }, { kind: "capacity", turret: k, add: 2 }] },
    { id: "range", name: "Reichweite", notableName: "Weitsicht", keystoneName: "Horizont", length: 10, small: [{ kind: "range", turret: k, add: 0.2 }], smallAlt: areaStep(k), notable: [{ kind: "range", turret: k, add: 1 }], keystone: [{ kind: "range", turret: k, add: 4 }] },
    { id: "turn", name: "Schwenken", notableName: "Servoantrieb", keystoneName: "Rundumblick", length: 8, small: [{ kind: "turnRate", turret: k, mul: 1.15 }], notable: [{ kind: "turnRate", turret: k, mul: 1.8 }], keystone: [{ kind: "turnRate", turret: k, mul: 4 }] },
  ];
}

interface GlobalTheme {
  id: string;
  name: string;
  keystoneName: string;
  small(): Effect[];
  notable(): Effect[];
  keystone(): Effect[];
}

const kindsDealing = (types: DamageType[]) => TURRET_TYPES.filter((t) => types.includes(t.damageType)).map((t) => t.id);
const allKinds = () => TURRET_TYPES.map((t) => t.id);
const each = (kinds: TurretKind[], f: (k: TurretKind) => Effect) => kinds.map(f);

const GLOBALS: GlobalTheme[] = [
  // #21: throughput first — fire rate and more turrets; damage only on the keystones, moderate.
  { id: "ballistics", name: "Ballistik", keystoneName: "Uranmunition", small: () => each(kindsDealing(["kinetic", "explosive"]), (k) => ({ kind: "fireRate", turret: k, mul: 1.03 })), notable: () => each(kindsDealing(["kinetic", "explosive"]), (k) => ({ kind: "capacity", turret: k, add: 1 })), keystone: () => each(kindsDealing(["kinetic", "explosive"]), (k) => ({ kind: "damage", turret: k, mul: 1.5 })) },
  { id: "thermal", name: "Thermik", keystoneName: "Sonnenkern", small: () => each(kindsDealing(["fire", "energy"]), (k) => ({ kind: "fireRate", turret: k, mul: 1.03 })), notable: () => each(kindsDealing(["fire", "energy"]), (k) => ({ kind: "capacity", turret: k, add: 1 })), keystone: () => each(kindsDealing(["fire", "energy"]), (k) => ({ kind: "damage", turret: k, mul: 1.5 })) },
  { id: "electrics", name: "Elektrik", keystoneName: "Supraleiter", small: () => each(kindsDealing(["electric"]), (k) => ({ kind: "fireRate", turret: k, mul: 1.04 })), notable: () => each(kindsDealing(["electric"]), (k) => ({ kind: "pattern", turret: k, field: "jumps", add: 1 })), keystone: () => each(kindsDealing(["electric"]), (k) => ({ kind: "fireRate", turret: k, mul: 2 })) },
  { id: "cooling", name: "Kühlung", keystoneName: "Flüssigstickstoff", small: () => each(allKinds(), (k) => ({ kind: "fireRate", turret: k, mul: 1.03 })), notable: () => each(allKinds(), (k) => ({ kind: "fireRate", turret: k, mul: 1.15 })), keystone: () => each(allKinds(), (k) => ({ kind: "fireRate", turret: k, mul: 2 })) },
  { id: "optics", name: "Optik", keystoneName: "Satellitenaufklärung", small: () => each(allKinds(), (k) => ({ kind: "range", turret: k, add: 0.05 })), notable: () => each(allKinds(), (k) => ({ kind: "range", turret: k, add: 0.3 })), keystone: () => each(allKinds(), (k) => ({ kind: "range", turret: k, add: 1.5 })) },
  { id: "logistics", name: "Logistik", keystoneName: "Massenfertigung", small: () => each(allKinds(), (k) => ({ kind: "turnRate", turret: k, mul: 1.05 })), notable: () => each(allKinds(), (k) => ({ kind: "capacity", turret: k, add: 1 })), keystone: () => each(allKinds(), (k) => ({ kind: "capacityMul", turret: k, mul: 1.5 })) },
];

export const TREE: ResearchNode[] = buildTree();
